import { createOpenAI } from "@ai-sdk/openai";
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { VOICE_INSTRUCTIONS, VOICE_MODEL, seedInput } from "@/lib/ai/voice-call";
import { voiceApiKey } from "@/lib/ai/configured";
import { VOICE_NEEDS_OPENAI_KEY } from "@/lib/ai/voice-access";
import { jsonBodyOrNull } from "@/lib/json-body";

const inputSchema = z.object({ sdp: z.string().min(1).max(20_000), conversationId: z.uuid() }).strict();

export async function POST(request: Request) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
  const parsed = inputSchema.safeParse(await jsonBodyOrNull(request));
  if (!parsed.success) return Response.json({ error: "Invalid call request" }, { status: 400 });
  const apiKey = await voiceApiKey();
  if (!apiKey) return Response.json({ error: VOICE_NEEDS_OPENAI_KEY }, { status: 503 });
  const { sdp, conversationId } = parsed.data;
  const { supabase, workspace, settings } = context;
  const [existing, messages] = await Promise.all([
    supabase.from("conversations").select("id, deleted_at").eq("workspace_id", workspace.id).eq("id", conversationId).maybeSingle(),
    supabase.from("messages").select("role, content").eq("workspace_id", workspace.id).eq("conversation_id", conversationId)
      .order("created_at", { ascending: false }).limit(10),
  ]);
  if (existing.error) throw existing.error;
  if (existing.data?.deleted_at) return Response.json({ error: "Conversation was deleted" }, { status: 404 });
  if (messages.error) throw messages.error;
  const history: { role: string; content: string }[] = existing.data ? (messages.data ?? []).reverse() : [];
  try {
    const session = await createOpenAI({ apiKey }).experimental_realtime(VOICE_MODEL).doCreateWebRTCSession({ sdp, abortSignal: request.signal, sessionConfig: {
      instructions: VOICE_INSTRUCTIONS, voice: settings.voice,
      providerOptions: { openai: { delegation: { type: "client" }, input: seedInput(history) } },
    } });
    return Response.json({ sdp: session.sdp, sessionId: session.sessionId, workspaceId: workspace.id });
  } catch (error) {
    console.error("voice session failed", error);
    return Response.json({ error: "Could not start the call" }, { status: 502 });
  }
}
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { VOICES } from "@/lib/settings";
import { voiceApiKey } from "@/lib/ai/configured";
import { VOICE_NEEDS_OPENAI_KEY } from "@/lib/ai/voice-access";

const querySchema = z.object({ voice: z.enum(VOICES) }).strict();
const SAMPLE_LINE = "Hey, it's Moneo. Want me to check your spending?";
const clips = new Map<string, Promise<ArrayBuffer>>();

function makeClip(voice: string, apiKey: string) {
  return fetch("https://api.openai.com/v1/audio/speech", {
    method: "POST", headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
    body: JSON.stringify({ model: "gpt-4o-mini-tts", voice, input: SAMPLE_LINE, response_format: "mp3" }),
  }).then(response => { if (!response.ok) throw new Error(`speech ${response.status}`); return response.arrayBuffer(); });
}

export async function GET(request: Request) {
  try { await requireWorkspace(); } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
  const parsed = querySchema.safeParse(Object.fromEntries(new URL(request.url).searchParams));
  if (!parsed.success) return Response.json({ error: "Unknown voice" }, { status: 400 });
  const apiKey = await voiceApiKey();
  if (!apiKey) return Response.json({ error: VOICE_NEEDS_OPENAI_KEY }, { status: 503 });
  const { voice } = parsed.data;
  if (!clips.has(voice)) clips.set(voice, makeClip(voice, apiKey));
  try {
    return new Response(await clips.get(voice)!, { headers: { "Content-Type": "audio/mpeg", "Cache-Control": "private, max-age=86400" } });
  } catch (error) {
    clips.delete(voice);
    console.error("voice sample failed", error);
    return Response.json({ error: "Could not play the sample" }, { status: 502 });
  }
}

