import type { SpeechEngineId } from "@/lib/settings";

export const SPEECH_ENGINE_LABELS: Record<SpeechEngineId, string> = { openai: "OpenAI", local: "On this computer", openrouter: "OpenRouter" };

export type SpeechAudio = { samples: Int16Array; sampleRate: number };
export type SpeechHints = { prompt: string; keywords: string[] };

export type BatchSpeechEngine = {
  available: () => Promise<boolean>;
  transcribe: (audio: SpeechAudio, hints: SpeechHints, signal?: AbortSignal) => Promise<string>;
  interim?: (audio: SpeechAudio, hints: SpeechHints) => Promise<string | null>;
};
export type BatchSpeechEngines = Partial<Record<SpeechEngineId, BatchSpeechEngine>>;

export type SpeechPlan = { mode: "live"; fellBack: boolean } | { mode: "batch"; engine: SpeechEngineId; fellBack: false; live: boolean };
import { requireWorkspace } from "@/lib/auth";
import { decodeSpeechAudio, MAX_SPEECH_BYTES } from "@/lib/ai/speech/audio";
import { transcribeWithFallback } from "@/lib/ai/speech/choose";
import { loadSpeechHints } from "@/lib/ai/speech/hints";
import { batchEngines } from "@/lib/ai/speech/registry";

export async function POST(request: Request) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
  if (Number(request.headers.get("content-length")) > MAX_SPEECH_BYTES) return Response.json({ error: "Recording is too long" }, { status: 413 });
  const bytes = new Uint8Array(await request.arrayBuffer());
  const audio = decodeSpeechAudio(request.headers.get("content-type"), new URL(request.url).searchParams.get("rate"), bytes);
  if (!audio) return Response.json({ error: "Invalid audio" }, { status: bytes.byteLength > MAX_SPEECH_BYTES ? 413 : 400 });
  const { supabase, workspace, settings } = context;
  const hints = await loadSpeechHints(supabase, workspace.id, settings.ai_data_scopes);
  const result = await transcribeWithFallback({ chosen: settings.speech_engine, engines: batchEngines(settings), audio, hints, signal: request.signal });
  if (!result.ok) return Response.json({ error: result.reason }, { status: result.status });
  return Response.json({ text: result.text, engine: result.engine, fellBack: result.fellBack }, { headers: { "Cache-Control": "no-store" } });
}
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { chooseSpeechEngine, speechAvailability } from "@/lib/ai/speech/choose";
import { loadSpeechHints } from "@/lib/ai/speech/hints";
import { batchEngines } from "@/lib/ai/speech/registry";
import { voiceApiKey } from "@/lib/ai/configured";
import { jsonBodyOrNull } from "@/lib/json-body";

const VOICE_MODEL = "gpt-live-transcribe";
const inputSchema = z.object({}).strict();
const secretSchema = z.object({ value: z.string().min(1), expires_at: z.number() });

export async function POST(request: Request) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
